const config = {
  "previewFeatures": [],
  "clientVersion": "7.7.0",
  "engineVersion": "75cbdc1eb7150937890ad5465d861175c6624711",
  "activeProvider": "postgresql",
  "inlineSchema": "// Ebright Flow — Prisma schema\n// Implements the build spec §4 + §4a, with the following deliberate additions\n// (each one flagged in PROJECT_GUIDE.md §\"Spec deviations\"):\n//   - Workspace model: spec §2 requires a Workspace → Flow → Run sidebar hierarchy,\n//     but §4 had no Workspace table. Added, with department scoping for §6 multi-tenancy.\n//   - FlowRun.templateSnapshot: spec snapshots only Flow.version (an Int). That does NOT\n//     preserve template *content* — editing Block rows in place would still mutate in-flight\n//     runs. The engine therefore snapshots the full executable template (nodes, edges,\n//     blocks+items, decisions) at run start and reads ONLY from the snapshot.\n//   - RunItem denormalizes type/label/required/config from the template item at run start,\n//     for the same reason.\n//   - Block.dueInHours: spec §5 schedules reminders relative to dueAt but nothing ever set\n//     dueAt. dueAt = activatedAt + dueInHours (falls back to reminder cadence from activation).\n//   - RunBlock.reminderJobId: lets completion cancel the pending BullMQ job by id (§5 requires\n//     real job removal, not ignoring).\n//   - AuditLog: §6 audit-trail requirement.\n//   - Block.escalateToUserId is nullable in the DB but REQUIRED to publish a flow —\n//     enforced by the publish validation, so half-built drafts can be saved.\n//   - User ids on non-identity tables are plain strings (no FK relation): the User table\n//     will eventually mirror OSC identities (§5a); loose coupling keeps that swap cheap.\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../../src/generated/task-manager-client\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ---------- Identity ----------\n\nmodel User {\n  id               String            @id @default(cuid())\n  email            String            @unique\n  name             String\n  role             Role              @default(MEMBER)\n  department       String?\n  branch           String? // org location dimension (e.g. \"Subang Taipan\") — analytics\n  employmentType   String? // HOD | Full Time | Part Time | Intern — display label, analytics\n  coachSchedule    String? // Full Time | Part Time — sub-split of employmentType \"Coach\" only;\n  // used by the assign-task recipient picker's \"By Group\" filter, NOT by the\n  // Branch Status by Region analytics (which still matches employmentType \"Coach\").\n  createdAt        DateTime          @default(now())\n  hodKanbanCards   HodKanbanCard[]\n  hodKanbanColumns HodKanbanColumn[] // DEPT_SITE/BRANCH_SITE view-only site logins for\n  // \"Department accounts\"/\"Branch site accounts\" (one department/branch's Status\n  // view, no personal tasks) — see role usage below.\n}\n\nenum Role {\n  ADMIN\n  CEO\n  OPS\n  BRANCH\n  HOD\n  MEMBER\n  DEPT_SITE // Department-level view-only login (e.g. \"Finance Department\") —\n  // sees only that department's own Department Status Daily/Monthly + member\n  // roster, no personal tasks, no assign form — EXCEPT the Operation\n  // department's account, which additionally gets unrestricted Assign Task\n  // (see /api/internal/assign's isOperationDeptSite check).\n  BRANCH_SITE // Branch-level view-only login (e.g. \"Subang Taipan\") — sees only\n  // that branch's own Branch Status Daily/Monthly + member roster, no\n  // personal tasks, no assign form, no Manpower Schedule.\n}\n\n// One HOD's own freeform personal board — NOT the task engine (no\n// RunBlock/FlowRun involved). 3 default columns (Pending/In Progress/\n// Completed) get lazily persisted here as real HodKanbanColumn rows\n// (owner-scoped ids) the first time that HOD's board is loaded (GET);\n// after that they're ordinary rows — renamable and deletable the same as\n// any custom column the HOD adds (HodKanbanColumn below). The HOD manually\n// creates and drags cards for their own notes/reminders. `order` is a\n// float (fractional-indexing style) so a drag to a specific position only\n// ever needs to update the ONE moved card. `column` is either one of the 3\n// fixed strings (\"PENDING\" | \"IN_PROGRESS\" | \"COMPLETED\") or a\n// HodKanbanColumn's own id.\nmodel HodKanbanCard {\n  id        String   @id @default(cuid())\n  ownerId   String\n  owner     User     @relation(fields: [ownerId], references: [id], onDelete: Cascade)\n  column    String\n  title     String\n  order     Float\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([ownerId, column])\n}\n\n// A column on an HOD's board: either one of the 3 defaults (Pending/In\n// Progress/Completed), lazily created as a row here the first time that\n// HOD's board is loaded (see HodKanbanCard above), or a custom column the\n// HOD added afterward. Once created, default and custom columns are\n// indistinguishable — every row here is equally renamable, reorderable,\n// and deletable.\nmodel HodKanbanColumn {\n  id        String   @id @default(cuid())\n  ownerId   String\n  owner     User     @relation(fields: [ownerId], references: [id], onDelete: Cascade)\n  label     String\n  order     Float\n  /**\n   * Preset key from HOD_KANBAN_COLORS (src/osc/types.ts), or null for the\n   * default neutral title — never a raw hex/CSS value.\n   */\n  color     String?\n  createdAt DateTime @default(now())\n\n  @@index([ownerId])\n}\n\n// ---------- Template layer (design-time) ----------\n\nmodel Workspace {\n  id         String   @id @default(cuid())\n  name       String\n  icon       String? // emoji shown in the sidebar\n  ownerId    String\n  department String?\n  order      Int      @default(0)\n  createdAt  DateTime @default(now())\n  flows      Flow[]\n}\n\nmodel Flow {\n  id            String         @id @default(cuid())\n  workspaceId   String\n  workspace     Workspace      @relation(fields: [workspaceId], references: [id])\n  name          String\n  icon          String? // emoji, for quick visual scanning in the sidebar\n  description   String?\n  ownerId       String\n  department    String?\n  order         Int            @default(0)\n  nodes         Json           @default(\"[]\") // React Flow nodes (block + decision), positions\n  edges         Json           @default(\"[]\") // React Flow edges; edge.data.condition per lib/types\n  version       Int            @default(1)\n  isPublished   Boolean        @default(false)\n  createdAt     DateTime       @default(now())\n  updatedAt     DateTime       @updatedAt\n  triggers      FlowTrigger[]\n  blocks        Block[]\n  decisionNodes DecisionNode[]\n  runs          FlowRun[]\n  doc           FlowDoc?\n\n  @@index([workspaceId])\n}\n\nmodel FlowTrigger {\n  id     String      @id @default(cuid())\n  flowId String\n  flow   Flow        @relation(fields: [flowId], references: [id], onDelete: Cascade)\n  type   TriggerType\n  config Json // FORM_SUBMIT: form field schema; WORKFLOW_CHAIN: { sourceFlowId }\n\n  @@index([flowId])\n}\n\nenum TriggerType {\n  MANUAL\n  FORM_SUBMIT\n  WORKFLOW_CHAIN\n}\n\n// A Block = one node on canvas = a mini checklist for ONE PIC\nmodel Block {\n  id               String      @id @default(cuid())\n  flowId           String\n  flow             Flow        @relation(fields: [flowId], references: [id], onDelete: Cascade)\n  nodeId           String // matches the React Flow node id in Flow.nodes\n  title            String\n  assigneeRole     String? // role/department placeholder, resolved at run time if not fixed\n  fixedAssigneeId  String? // optional: always assign to this specific user\n  dueInHours       Int? // dueAt = activation + dueInHours (see header note)\n  reminderInterval Int         @default(24) // hours between reminders\n  strikeLimit      Int         @default(3)\n  escalateToUserId String? // supervisor; REQUIRED at publish time (validated, not by the DB)\n  outgoingEdges    Json        @default(\"[]\") // ConditionalEdge[] (lib/types) — first match wins\n  items            BlockItem[]\n\n  @@unique([flowId, nodeId])\n}\n\nmodel BlockItem {\n  id       String   @id @default(cuid())\n  blockId  String\n  block    Block    @relation(fields: [blockId], references: [id], onDelete: Cascade)\n  order    Int\n  type     ItemType\n  label    String\n  required Boolean  @default(true)\n  config   Json     @default(\"{}\") // per-type config, zod-validated (lib/item-schemas)\n\n  @@index([blockId, order])\n}\n\nenum ItemType {\n  CHECKBOX\n  TEXT\n  YES_NO\n  NUMBER\n  DROPDOWN\n  DUE_DATE\n  FILE_UPLOAD\n  APPROVAL\n  SUB_ASSIGNEE_TASK\n  IMAGE_EMBED\n}\n\n// Decision node = flowchart diamond for multi-way branches\nmodel DecisionNode {\n  id         String @id @default(cuid())\n  flowId     String\n  flow       Flow   @relation(fields: [flowId], references: [id], onDelete: Cascade)\n  nodeId     String\n  conditions Json   @default(\"[]\") // ConditionalEdge[] — ordered, first match wins, 'else' last\n\n  @@unique([flowId, nodeId])\n}\n\n// ---------- Execution layer (run-time) ----------\n\nmodel FlowRun {\n  id               String      @id @default(cuid())\n  flowId           String\n  flow             Flow        @relation(fields: [flowId], references: [id])\n  flowVersion      Int // Flow.version at start\n  templateSnapshot Json // full executable template at start — engine reads ONLY this\n  name             String // display name, e.g. \"Client Onboarding — 16 Jul\"\n  startedById      String\n  triggerType      TriggerType\n  status           RunStatus   @default(ACTIVE)\n  startedAt        DateTime    @default(now())\n  completedAt      DateTime?\n  runBlocks        RunBlock[]\n\n  @@index([flowId, status])\n  @@index([status, startedAt])\n}\n\nenum RunStatus {\n  ACTIVE\n  COMPLETED\n  CANCELLED\n}\n\nmodel RunBlock {\n  id             String      @id @default(cuid())\n  runId          String\n  run            FlowRun     @relation(fields: [runId], references: [id], onDelete: Cascade)\n  blockId        String // template Block id (as captured in the snapshot)\n  nodeId         String // canvas node id — used for edge navigation within the snapshot\n  title          String // denormalized for dashboard queries\n  assigneeId     String\n  status         BlockStatus @default(PENDING)\n  dueAt          DateTime?\n  strikeCount    Int         @default(0)\n  reminderJobId  String? // current pending BullMQ job id, cancelled on completion\n  startedAt      DateTime?\n  completedAt    DateTime?\n  scheduleSlotId String? // set when this task was created by a Manpower Schedule slot sync\n  runItems       RunItem[]\n  // Explicit Daily/Monthly/Ad hoc tag, set ONLY by the \"+ Add Task\" quick-\n  // assign form (assign/route.ts) for its 5 permitted actor roles. A task\n  // gets EXACTLY ONE of these, never more — the form is single-select.\n  // null (the default, and every pre-existing row from before this field\n  // existed) means \"untagged\" — the OLD dueAt/startedAt date-window rule\n  // (resolveWindow/fetchPeriodBlocks) still decides Daily/Monthly membership\n  // for those, and the OLD starter-role check still decides Ad hoc\n  // membership (getAdhocPayload/getAdhocRegionsPayload). A non-null value\n  // means the tag ALONE decides Daily/Monthly membership — dueAt becomes\n  // purely a deadline/overdue marker for these tasks — and ADHOC (settable\n  // only when the assignee is a Branch Manager) ORs into the existing\n  // starter-role Ad hoc check. Every other creation path (Manpower Schedule\n  // slot sync, engine flow runs) leaves this at its default (null) and is\n  // completely unaffected.\n  cadence        Cadence?\n  // Weekly auto-recurrence — \"recurring series\" model: when a DAILY block's\n  // due day has passed, engine/recurrence.ts (hourly in-server sweep +\n  // lazy catch-up on read) creates NEXT week's occurrence and links it back\n  // via recurrenceOfId. The finished block is never touched, so per-day\n  // history (the Daily date filter) keeps showing what actually happened.\n  // recurrenceOfId is UNIQUE — at most ONE successor per block — making\n  // concurrent catch-ups idempotent. Manpower-Schedule tasks\n  // (scheduleSlotId set, cadence ADHOC) never qualify.\n  //\n  // repeatWeekly is RETIRED (2026-07-25 final decision: recurrence is\n  // UNIVERSAL for Daily tasks — no opt-in). Column kept to avoid a\n  // pointless destructive migration; nothing reads or writes it anymore.\n  repeatWeekly   Boolean     @default(false)\n  recurrenceOfId String?     @unique\n  recurrenceOf   RunBlock?   @relation(\"BlockRecurrence\", fields: [recurrenceOfId], references: [id])\n  successor      RunBlock?   @relation(\"BlockRecurrence\")\n\n  // Optional SOP/reference material attached by the assigner (2026-07-30,\n  // the \"+ Task\" Guideline section). ONE Guideline row is shared by every\n  // block the assignment created (all recipients × days) and by weekly-\n  // recurrence successors — the image bytes are stored once.\n  guidelineId String?\n  guideline   Guideline? @relation(fields: [guidelineId], references: [id])\n\n  // Optional assignee-uploaded completion evidence (2026-07-30, the My\n  // Tasks \"Proof\" column). Unlike guideline (shared, assigner-attached),\n  // proof is strictly per-block and NEVER inherited by recurrence\n  // successors — it's evidence for THIS occurrence only.\n  proof Proof?\n\n  @@unique([runId, nodeId])\n  @@index([assigneeId, status])\n  @@index([status, dueAt])\n  @@index([runId])\n  @@index([repeatWeekly, dueAt])\n}\n\n/// Optional assigner-attached reference material for a task (link and/or\n/// image, both optional — but a row only exists when at least one is set).\n/// Image bytes live here in the DB (capped at 2 MB by the assign action)\n/// so dev/staging/prod share them and Docker redeploys can't lose them;\n/// served via /api/task-manager/guideline-image/[id] (session-gated).\nmodel Guideline {\n  id        String     @id @default(cuid())\n  url       String?\n  imageMime String? // image/png | image/jpeg | image/webp\n  imageData Bytes?\n  createdAt DateTime   @default(now())\n  blocks    RunBlock[]\n}\n\n/// Assignee-uploaded completion evidence for ONE RunBlock (a screenshot —\n/// image only, capped at 2 MB by the upload action). Optional: uploading\n/// proof never gates completion. Re-uploading replaces the row (upsert on\n/// runBlockId); deleting the block cascades the proof away. Bytes live in\n/// the DB for the same reason as Guideline.imageData; served via\n/// /api/task-manager/proof-image/[id] (session-gated).\nmodel Proof {\n  id         String   @id @default(cuid())\n  runBlockId String   @unique\n  runBlock   RunBlock @relation(fields: [runBlockId], references: [id], onDelete: Cascade)\n  imageMime  String // image/png | image/jpeg | image/webp\n  imageData  Bytes\n  createdAt  DateTime @default(now())\n}\n\nenum BlockStatus {\n  PENDING\n  ACTIVE\n  OVERDUE\n  ESCALATED\n  DONE\n  SKIPPED\n}\n\nenum Cadence {\n  DAILY\n  MONTHLY\n  // Set ONLY on tasks assigned (via /api/internal/assign) to a Branch\n  // Manager assignee — the one branch-side role that keeps all 3 cadence\n  // options. Coach/Branch Exec assignees never get this value (their\n  // Cadence field only ever offers Daily). getAdhocPayload/\n  // getAdhocRegionsPayload OR this tag in alongside the pre-existing\n  // starter-role === BRANCH check.\n  ADHOC\n}\n\nmodel RunItem {\n  id          String    @id @default(cuid())\n  runBlockId  String\n  runBlock    RunBlock  @relation(fields: [runBlockId], references: [id], onDelete: Cascade)\n  itemId      String // template BlockItem id (as captured in the snapshot)\n  order       Int\n  type        ItemType // denormalized from the snapshot — immune to template edits\n  label       String\n  required    Boolean\n  config      Json      @default(\"{}\")\n  value       Json? // typed answer, shape per lib/item-schemas value schema\n  completedAt DateTime?\n  completedBy String?\n\n  @@index([runBlockId, order])\n}\n\nmodel NotificationLog {\n  id         String   @id @default(cuid())\n  runBlockId String\n  type       String // REMINDER | ESCALATION\n  sentTo     String\n  sentAt     DateTime @default(now())\n  jobId      String // BullMQ job id, for tracing/debugging\n\n  @@index([runBlockId])\n}\n\n// §6 audit trail: who did what, when — answerable without digging through email\nmodel AuditLog {\n  id         String   @id @default(cuid())\n  runId      String?\n  runBlockId String?\n  actorId    String // user id, or \"system\" for engine/worker actions\n  action     String // RUN_STARTED | RUN_COMPLETED | RUN_CANCELLED | ITEM_COMPLETED | ITEM_CLEARED | BLOCK_STATUS_CHANGED | BLOCK_ESCALATED | BLOCK_REASSIGNED | BLOCK_RECURRED | BLOCK_AUTO_REFRESH (historical only) | REMINDER_SENT\n  detail     Json?\n  createdAt  DateTime @default(now())\n\n  @@index([runId, createdAt])\n  @@index([runBlockId])\n}\n\n// ---------- §4a Wiki page + saved dashboard views ----------\n\n// One attached doc per Flow — SOP notes/context; deliberately NOT versioned with Flow.version\nmodel FlowDoc {\n  id        String   @id @default(cuid())\n  flowId    String   @unique\n  flow      Flow     @relation(fields: [flowId], references: [id], onDelete: Cascade)\n  content   Json // BlockNote document JSON\n  updatedAt DateTime @updatedAt\n  updatedBy String\n}\n\nmodel SavedView {\n  id        String   @id @default(cuid())\n  userId    String\n  name      String\n  viewType  ViewType\n  filters   Json     @default(\"{}\") // status, assignee, flow, overdue-only, etc.\n  sortBy    String?\n  isDefault Boolean  @default(false)\n\n  @@index([userId])\n}\n\nenum ViewType {\n  TABLE\n  BOARD\n  CALENDAR\n}\n\n// ---------- Manpower schedule (OSC bridge) ----------\n\n// A branch manager's weekly/daily staffing grid: rows are time slots,\n// columns are role seats (Manager / Coach N / Exec N, configurable per\n// branch). One row per (branch, date). Assignments only sync to the task\n// engine once PUBLISHED — PLANNING is a draft the branch manager can edit\n// freely without notifying anyone.\nmodel ManpowerSchedule {\n  id          String         @id @default(cuid())\n  branch      String\n  date        String // YYYY-MM-DD\n  status      ScheduleStatus @default(PLANNING)\n  createdById String\n  publishedAt DateTime?\n  createdAt   DateTime       @default(now())\n  updatedAt   DateTime       @updatedAt\n  slots       ScheduleSlot[]\n\n  @@unique([branch, date])\n}\n\nenum ScheduleStatus {\n  PLANNING\n  PUBLISHED\n}\n\n// One grid cell: a (time row × role column) pair. assignedStaffId is who's\n// on that seat for that slot; runBlockId is the linked ad hoc task once the\n// schedule is published and the cell is assigned — kept in sync on every\n// reassignment/unassignment/time edit (see src/app/api/internal/_manpower.ts).\nmodel ScheduleSlot {\n  id              String           @id @default(cuid())\n  scheduleId      String\n  schedule        ManpowerSchedule @relation(fields: [scheduleId], references: [id], onDelete: Cascade)\n  startTime       String // HH:mm\n  endTime         String // HH:mm\n  roleColumn      String // \"Manager\" | \"Coach 1\" | \"Exec 1\" | ...\n  assignedStaffId String?\n  runBlockId      String?\n  updatedAt       DateTime         @updatedAt\n\n  @@unique([scheduleId, startTime, endTime, roleColumn])\n  @@index([scheduleId])\n}\n\n// ---------- CEO dashboard customization (OSC bridge) ----------\n\n// One row per CEO user PER CADENCE (\"daily\" | \"monthly\"): which departments\n// they've pinned to that Kanban board, and in what order. The Daily and\n// Monthly boards are fully independent — adding/removing/reordering on one\n// never touches the other. Personal to that CEO — doesn't affect\n// Superadmin's or anyone else's view. `departments` is an ordered JSON\n// string array of official department names.\nmodel CeoDashboardConfig {\n  id          String   @id @default(cuid())\n  userId      String\n  cadence     String\n  departments Json     @default(\"[]\")\n  updatedAt   DateTime @updatedAt\n\n  @@unique([userId, cadence])\n}\n"
}

